# %% ../nbs/01_config.ipynb #ec15b49e
@dataclass(frozen=True)
class AudioJEPAConfig:
    """Audio-JEPA context encoder. Frontend fields describe the Kaldi fbank."""

    sample_rate: int = 32_000
    clip_length: float = 10.0
    n_mels: int = 128
    time_bins: int = 256
    patch_h: int = 16
    patch_w: int = 16
    in_chans: int = 1
    embed_dim: int = 768
    depth: int = 12
    num_heads: int = 12
    mlp_ratio: float = 4.0
    qkv_bias: bool = True
    layer_norm_eps: float = 1e-5
    f_min: float = 20.0

    def __post_init__(self) -> None:
        if self.time_bins % self.patch_h:
            raise ValueError(f"{self.time_bins} time bins do not divide into patch height {self.patch_h}")
        if self.n_mels % self.patch_w:
            raise ValueError(f"{self.n_mels} mels do not divide into patch width {self.patch_w}")
        if self.embed_dim % self.num_heads:
            raise ValueError(f"{self.embed_dim} is not divisible by {self.num_heads} heads")

    @property
    def patch_size(self) -> tuple[int, int]:
        return (self.patch_h, self.patch_w)

    @property
    def f_max(self) -> float:
        return self.sample_rate / 2

    @property
    def hop_length_ms(self) -> float:
        """Kaldi frame shift in milliseconds."""
        return (self.clip_length * 1000) / self.time_bins

    @property
    def frame_length_ms(self) -> float:
        """Kaldi frame length in milliseconds. Audio-JEPA uses 2.5 hops."""
        return 2.5 * self.hop_length_ms

    @property
    def head_dim(self) -> int:
        return self.embed_dim // self.num_heads

    @property
    def mlp_hidden(self) -> int:
        return int(self.embed_dim * self.mlp_ratio)

    @property
    def grid_time(self) -> int:
        """Patch rows. The spectrogram height is time."""
        return self.time_bins // self.patch_h

    @property
    def grid_freq(self) -> int:
        """Patch columns. The spectrogram width is mel."""
        return self.n_mels // self.patch_w

    @property
    def num_patches(self) -> int:
        return self.grid_time * self.grid_freq

    @property
    def clip_samples(self) -> int:
        return int(self.clip_length * self.sample_rate)


